                        rule_results[fact_name] = [formatted_val, doc_name]
                    except (TypeError, ValueError):
                        rule_results[fact_name] = "ABSENT"
                else:
                    # Dates or other strings
                    rule_results[fact_name] = [str(val), doc_name]

        results[pair_str] = rule_results

    print(json.dumps(results))

